        d = collections.defaultdict(list)
        for i, v in enumerate(arr):
            d[v].append(i)
        vis = set([0])
        q = deque()
        q.append((0, 0))
        while q:
            idx, step = q.popleft()
            if idx == len(arr) - 1:
